    "difficulty": 2,
    "question": "手引に従い、与えられた記号と英字をその順に平仮名へ置き換えた組合せを選べ。\n与えられた組合せ：♣　A　△　Y\n\n【手引】平仮名（記号、英字）\nけ（□、N）｜と（♣、P）｜も（△、J）｜な（☆、L）｜う（◆、W）｜た（◎、K）｜や（▼、A）｜そ（●、G）｜す（◇、D）｜り（♤、Y）",
    "choices": {
      "ア": "とやたそ",
      "イ": "とやもり",
      "ウ": "もすそう",
      "エ": "もなたす",
      "オ": "やもりと"
    },
    "answer": "イ",
    "officialAnswerNumber": 2,
    "explanation": "手引で与えられた記号と英字を順に照合すると、「♣」→「と」、「A」→「や」、「△」→「も」、「Y」→「り」となる。元の順のまま並べると「とやもり」になる。",
    "choiceExplanations": {
      "ア": "3文字目の「△」は、手引では「も」に対応する。選択肢の「た」とは異なる。",
      "イ": "手引で与えられた記号と英字を順に照合すると、「♣」→「と」、「A」→「や」、「△」→「も」、「Y」→「り」となる。元の順のまま並べると「とやもり」になる。",
      "ウ": "1文字目の「♣」は、手引では「と」に対応する。選択肢の「も」とは異なる。",
      "エ": "1文字目の「♣」は、手引では「と」に対応する。選択肢の「も」とは異なる。",
      "オ": "1文字目の「♣」は、手引では「と」に対応する。選択肢の「や」とは異なる。"
    },
